# ===== Value model and inference =====
class MValue:
    __slots__ = ('typ','val','orig')
    def __init__(self, typ, val, orig=None):
        self.typ = typ  # 'int','float','string','bool','null','array','map','void','absent','error'
        self.val = val
        self.orig = orig  # original string if from input/literal
    def __repr__(self):
        return f"MValue({self.typ},{self.val!r},{self.orig!r})"

def infer_value(s, infer_none=False, infer_octal=False):
    if infer_none:
        return MValue('string', s, s)
    # empty?
    if s == "":
        return MValue('string', "", "")
    # bool? No, DKVP/CSV true/false stay strings (observed). So only numbers.
    # Try int/float inference
    # Rules: leading zeros? "01" stays string, "00" stays string? Check: "01" -> string, "0" -> int 0. What about "00"? Let's test.
    # For now: if s has leading zero and len>1 and second char is digit, then string (unless hex/oct/bin?).
    # Hex: 0x..., Oct: 0o..., Bin: 0b...
    # Else try int, then float.
    # Need to handle +/-, ., e/E, etc.
    # Use regex?
    if s.startswith("0x") or s.startswith("0X") or s.startswith("+0x") or s.startswith("-0x"):
        try:
            # hex
            v = int(s, 16)
            return MValue('int', v, None)  # orig None -> will format as decimal
        except:
            return MValue('string', s, s)
    if s.startswith("0o") or s.startswith("0O") or s.startswith("+0o") or s.startswith("-0o"):
        try:
            v = int(s, 8)
            return MValue('int', v, None)
        except:
            return MValue('string', s, s)
    if s.startswith("0b") or s.startswith("0B") or s.startswith("+0b") or s.startswith("-0b"):
        try:
            v = int(s, 2)
            return MValue('int', v, None)
        except:
            return MValue('string', s, s)
    # Octal with --infer-octal? Default? Test: "010" without flag?
    # Earlier --infer-octal flag exists. Default "010" likely string? Let's assume default string for leading zero.
    # Check: infer-octal flag would make "010" -> 8? Need to handle.
    # For infer_octal True, try octal for leading zero?
    # We'll implement: if infer_octal and s matches 0[0-7]+, parse octal.
    if infer_octal:
        if re.match(r'^[+-]?0[0-7]+$', s):
            try:
                v = int(s, 8)
                return MValue('int', v, None)
            except:
                pass
    # Leading-zero check: if matches ^[+-]?0[0-9] then string (like "01", "00", "01.5"?)
    if re.match(r'^[+-]?0[0-9]', s):
        return MValue('string', s, s)
    # Try int
    if re.match(r'^[+-]?[0-9]+$', s):
        try:
            v = int(s)
            return MValue('int', v, s)  # preserve orig for ints? For decimal ints, orig same as decimal, so fine. But store orig to preserve? e.g., "+1" vs "1"? Does Miller preserve "+1"? Let's test later. For now store orig.
        except:
            pass
    # Try float: patterns like 1., .5, 1.5, 1e10, 1E-3, etc.
    # Observed: ".5" -> float .5 with orig ".5", "1." -> float 1. with orig "1.", "1e3" -> float, etc. "inf" stays string.
    # Regex for float: ^[+-]?([0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)([eE][+-]?[0-9]+)?$ but must contain . or e/E to be float (else int)
    if re.match(r'^[+-]?([0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)[eE][+-]?[0-9]+$', s) or re.match(r'^[+-]?([0-9]+\.[0-9]*|\.[0-9]+)$', s):
        try:
            v = float(s)
            # check for inf/nan? float("inf") would succeed but we want string for "inf"? Observed "inf" stays string.
            # So if s lower is inf/nan/infinity, return string.
            ls = s.lower().lstrip("+-")
            if ls in ("inf","infinity","nan"):
                return MValue('string', s, s)
            return MValue('float', v, s)
        except:
            return MValue('string', s, s)
    return MValue('string', s, s)

def mvalue_from_python(obj, orig=None):
    # for JSON parsing with raw preservation, we handle separately
    if obj is None:
        return MValue('null', None, orig)
    if isinstance(obj, bool):
        return MValue('bool', obj, orig)
    if isinstance(obj, int):
        return MValue('int', obj, orig if orig is not None else str(obj))
    if isinstance(obj, float):
        # check inf/nan?
        return MValue('float', obj, orig)
    if isinstance(obj, str):
        return MValue('string', obj, obj)
    if isinstance(obj, list):
        return MValue('array', [mvalue_from_python(x) for x in obj], None)
    if isinstance(obj, dict):
        return MValue('map', OrderedDict((k, mvalue_from_python(v)) for k,v in obj.items()), None)
    return MValue('string', str(obj), str(obj))

def format_mvalue_for_dkvp(mv, ofmt=None):
    # ofmt handling for floats? --ofmt applies to output? For DKVP/CSV? It formats floats via sprintf.
    # If ofmt is set and mv is float/int, format accordingly.
    if ofmt is not None and mv.typ in ('int','float'):
        try:
            # ofmt like %.2f etc. Use Python % formatting? Go uses fmt package with % codes. Python % similar for floats.
            # For int with float fmt? e.g., %.2f on int 1 -> "1.00"? Likely.
            num = mv.val
            # Python's % formatting for %g, %e, %f should be similar.
            return ofmt % (num,)
        except Exception:
            pass
    if mv.typ == 'int':
        if mv.orig is not None and isinstance(mv.orig, str):
            # For inferred ints from hex/oct/bin, orig is None -> format decimal. For decimal ints, orig is decimal string, but should we output orig or decimal? For "+1" vs "1"? Need to check Miller preserves "+1"? Let's test later. For now, if orig looks like decimal int with same value, output orig? Or output str(val)? For "01" we wouldn't be int. For "+1", int 1, orig "+1" -> output "+1" or "1"? Miller likely preserves? We'll output orig if present.
            # But for computed ints, orig is None? Actually computed ints have orig None, so str(val).
            # For inferred decimal ints, orig == str(val) except for "+1" case. We'll output orig to preserve.
            return mv.orig
        return str(mv.val)
    elif mv.typ == 'float':
        if mv.orig is not None:
            return mv.orig
        # computed float: format Go-style 'f' without exponent? Use Python logic:
        f = mv.val
        if math.isnan(f):
            return "NaN"
        if math.isinf(f):
            return "+Inf" if f>0 else "-Inf"
        # If integer-valued, format as int (no decimal)
        if f.is_integer():
            # Check range: if abs < 1e21, format as int without exponent, else? Miller expanded even 1e30 as decimal, so always int?
            try:
                return str(int(f))
            except:
                pass
        # Otherwise, use repr with conversion to decimal if exponent?
        s = repr(f)
        # Python repr may give '1e-05' etc. Miller gives '0.00001'. Convert exponent to decimal?
        if 'e' in s or 'E' in s:
            # Convert to decimal string without exponent, shortest?
            # Use format with 'f' and strip?
            # Use Decimal for exact shortest? We'll use Python's decimal with high precision via repr's significant digits?
            # Simpler: use format(f, '.17f').rstrip('0').rstrip('.')? But for 1e-5, '.17f' gives '0.00001000000000000' -> stripped '0.00001' correct. For 1e-10, '.17f' gives '0.00000000010000000' -> stripped '0.0000000001' correct? Let's see: format(1e-10, '.17f') = '0.00000000010000000' -> stripped '0.0000000001' correct. For 1e30, '.17f' would be huge with many zeros? format(1e30, '.17f') = '1000000000000000019884624838656.00000000000000000'? That's wrong due to binary representation. But Miller gave '1000000000000000000000000000000' (exact power of 10). Python's float 1e30 is not exact, but repr is '1e+30', Miller's expanded is '1000000000000000000000000000000' (which is also not exact? 1e30 exact decimal is 1 followed by 30 zeros, but binary float is approx. Miller's output is exact power of 10, not the binary approx. So Miller's formatting for large powers of 10 gives exact decimal, not binary approx. That suggests it formats via decimal conversion of binary? Hmm.
            # For now, if exponent, try to format via '{:.15f}'.format? Not perfect.
            # We'll attempt to use g format then expand?
            # Use decimal module with string of repr?
            try:
                from decimal import Decimal
                # Use Decimal(str(f))? str(f) is repr with exponent, Decimal will parse exponent exactly as binary? Actually Decimal('1e+30') is exact 1e30, not binary approx. That's what Miller does (exact power of 10). So expanding exponent via Decimal gives exact power of 10, matching Miller.
                d = Decimal(s)
                # Format with 'f'
                sf = format(d, 'f')
                # Strip trailing zeros? For 1e-5, Decimal('1e-05') -> '0.00001' correct. For 1e30 -> '1000000000000000000000000000000' correct.
                # For 0.30000000000000004, Decimal('0.30000000000000004') -> '0.30000000000000004' correct.
                return sf
            except Exception:
                return s
        return s
    elif mv.typ == 'string':
        return mv.val
    elif mv.typ == 'bool':
        return "true" if mv.val else "false"
    elif mv.typ == 'null':
        return "null"
    elif mv.typ == 'array':
        # For DKVP, arrays flattened? Actually DKVP output for arrays? When JSON arrays output to DKVP, they are flattened to a.1 etc. So this case shouldn't happen for top-level DKVP writer (records are flat). But for nested values inside put? They would be flattened? We'll just json-encode?
        return json.dumps([format_mvalue_for_dkvp(x) if isinstance(x, MValue) else str(x) for x in mv.val])
    elif mv.typ == 'map':
        return json.dumps({k: (format_mvalue_for_dkvp(v) if isinstance(v, MValue) else str(v)) for k,v in mv.val.items()})
    elif mv.typ in ('void','absent','error'):
        return ""
    else:
        return str(mv.val)

