class DSLParser:
    def __init__(self, tokens):
        self.toks=tokens
        self.pos=0
    def peek(self):
        return self.toks[self.pos]
    def next(self):
        t=self.toks[self.pos]
        self.pos+=1
        return t
    def expect(self, typ, val=None):
        t=self.peek()
        if t.typ!=typ or (val is not None and t.val!=val):
            raise DSLParseError(f"expected {typ} {val}, got {t.typ} {t.val}")
        return self.next()
    def match(self, typ, val=None):
        t=self.peek()
        if t.typ==typ and (val is None or t.val==val):
            return self.next()
        return None
    def parse_program(self):
        stmts=[]
        begins=[]
        ends=[]
        while self.peek().typ!='EOF':
            # Skip semicolons
            if self.match('SEMI'):
                continue
            # Check for begin/end
            if self.peek().typ=='BEGIN':
                self.next()
                self.expect('LBRACE')
                bstmts=self.parse_block()
                self.expect('RBRACE')
                begins.append(('begin', bstmts))
                continue
            if self.peek().typ=='END':
                self.next()
                # end may be followed by { ... } or single statement? In Miller, end { ... }. Also bare 'end'?
                if self.match('LBRACE'):
                    estmts=self.parse_block()
                    self.expect('RBRACE')
                    ends.append(('end', estmts))
                else:
                    ends.append(('end', []))
                continue
            stmt=self.parse_statement()
            if stmt is not None:
                stmts.append(stmt)
            # Optional semicolon
            self.match('SEMI')
        return {'main': stmts, 'begins': begins, 'ends': ends}
    def parse_block(self):
        stmts=[]
        while self.peek().typ not in ('RBRACE','EOF'):
            if self.match('SEMI'):
                continue
            # Nested begin/end not allowed inside? Ignore.
            stmt=self.parse_statement()
            if stmt is not None:
                stmts.append(stmt)
            self.match('SEMI')
        return stmts
    def parse_statement(self):
        t=self.peek()
        if t.typ=='IF':
            return self.parse_if()
        if t.typ=='FOR':
            return self.parse_for()
        if t.typ=='WHILE':
            return self.parse_while()
        if t.typ=='DO':
            return self.parse_do()
        if t.typ in ('FUNC','FUNCT'):
            return self.parse_func()
        if t.typ=='SUBR':
            return self.parse_subr()
        if t.typ=='CALL':
            return self.parse_call()
        if t.typ=='RETURN':
            self.next()
            expr=None
            if self.peek().typ not in ('SEMI','RBRACE','EOF'):
                expr=self.parse_expr()
            return ('return', expr)
        if t.typ in ('BREAK','CONTINUE'):
            self.next()
            return (t.val, None)
