            if i+1>=len(args): sys.stderr.write(f'mlr: mlr {which}: option "-f" missing argument(s)\n'); sys.exit(1)
            f_fields=parse_field_list(args[i+1]); i+=2
        elif a=='-n':
            if i+1>=len(args): sys.stderr.write(f'mlr: mlr {which}: option "-n" missing argument(s)\n'); sys.exit(1)
            try: n=int(args[i+1])
            except: sys.stderr.write(f'mlr: mlr {which}: could not scan flag "{args[i+1]}" argument "{args[i+1]}" as int\n'); sys.exit(1)
            i+=2
        elif a=='-b': b_flag=True; i+=1
        elif a=='-o':
            if i+1>=len(args): sys.stderr.write(f'mlr: mlr {which}: option "-o" missing argument(s)\n'); sys.exit(1)
            o_name=args[i+1]; i+=2
        elif a.startswith('-'): sys.stderr.write(f'mlr: mlr {which}: option "{a}" not recognized\n'); sys.exit(1)
        else: sys.stderr.write(f'mlr: mlr {which}: option "{a}" not recognized\n'); sys.exit(1)
    if f_fields is None:
        sys.stderr.write(f'mlr: mlr {which}: -f field names required\n'); sys.exit(1)
    out=[]
    for f in f_fields:
        freq=OrderedDict(); order=[]
        for od,_,_ in records:
            v=od.get(f, MValue('string',"",""))
            key=format_mvalue_for_dkvp(v, None)
            if key not in freq:
                freq[key]=(v,1)
                order.append(key)
            else:
                old,cnt=freq[key]
                freq[key]=(old,cnt+1)
        # Sort by count: most-frequent descending, least ascending. For ties, first-found wins? Actually first-found wins tie means stable sort by count, preserving first order for ties.
        if which=='most-frequent':
            sorted_keys=sorted(order, key=lambda k: freq[k][1], reverse=True)
        else:
            sorted_keys=sorted(order, key=lambda k: freq[k][1])
        for key in sorted_keys[:n]:
            v,cnt=freq[key]
            new_od=OrderedDict()
            new_od[f]=v
            if not b_flag:
                new_od[o_name]=MValue('int', cnt, str(cnt))
            out.append((new_od, f"({which})", 1))
    return out

