def verb_sec2gmt_verb(records, args, opt, which):
    # sec2gmt with -1..-9, --millis etc. sec2gmtdate takes field list as positional?
    # For sec2gmtdate: usage "mlr sec2gmtdate {comma-separated list}" (no options, just field list)
    # For sec2gmt: options -1..-9, --millis etc., plus field list
    decimals=None; millis=False; micros=False; nanos=False
    fields=None
    i=0
    while i < len(args):
        a=args[i]
        if a in ('-h','--help'):
            sys.stdout.write(get_verb_help_for_dashhelp(which)); sys.exit(0)
        elif a in ('-1','-2','-3','-4','-5','-6','-7','-8','-9'):
            decimals=int(a[1]); i+=1
        elif a=='--millis': millis=True; i+=1
        elif a=='--micros': micros=True; i+=1
        elif a=='--nanos': nanos=True; i+=1
        elif a.startswith('-'): sys.stderr.write(f'mlr: mlr {which}: option "{a}" not recognized\n'); sys.exit(1)
        else:
            if fields is None:
                fields=parse_field_list(a)
            else:
                fields+=parse_field_list(a)
            i+=1
    if fields is None:
        sys.stderr.write(f'mlr: mlr {which}: field names required\n'); sys.exit(1)
    out=[]
    for od, fname, fnum in records:
        new_od=OrderedDict(od)
        for f in fields:
            if f not in od: continue
            v=od[f]
            try:
                sec=float(format_mvalue_for_dkvp(v, None))
                if millis: sec/=1000.0
                elif micros: sec/=1e6
                elif nanos: sec/=1e9
                dt=datetime.datetime.utcfromtimestamp(sec)
                if which=='sec2gmtdate':
                    s=dt.strftime("%Y-%m-%d")
                else:
                    base=dt.strftime("%Y-%m-%dT%H:%M:%S")
                    if decimals is not None:
                        frac=sec-math.floor(sec)
                        # Format fractional with decimals places
                        fmt=f"{{:.{decimals}f}}"
                        frac_str=fmt.format(frac)[1:]  # ".123"
                        s=base+frac_str+"Z"
                    else:
                        # If sec has fractional and decimals not specified? Probably no fractional? For integer sec, no fractional. For float sec, include? Unclear. We'll include fractional if non-integer?
                        if not float(sec).is_integer():
                            # Include 6 decimals? Or minimal? For simplicity, no fractional? Actually sec2gmt without -1..-9 probably truncates? Let's just output without fractional.
                            s=base+"Z"
                        else:
                            s=base+"Z"
                new_od[f]=MValue('string', s, s)
            except:
                pass
        out.append((new_od, fname, fnum))
    return out

